import os
from datadog_api_client import ApiClient, Configuration
from datadog_api_client.v1.api.metrics_api import MetricsApi
from datadog_api_client.v1.api.service_definitions_api import ServiceDefinitionsApi
from datadog_api_client.v1.models import MetricQueryDataType, MetricQueryDefinition, MetricQueryForm, MetricQueryFormType, MetricQueryMetadata, MetricQueryResponse, MetricResourceQueryDefinition

def compare_metric_series(payload, config=None):
    config = config or {}

    # Set up Datadog API client configuration
    configuration = Configuration()
    configuration.api_key = {"apiKeyAuth": os.getenv("DATADOG_API_KEY")}
    configuration.api_key["appKeyAuth"] = os.getenv("DATADOG_APP_KEY")

    with ApiClient(configuration) as api_client:
        # Initialize API client for metrics
        api_instance = MetricsApi(api_client)

        # Extract parameters from payload
        metric_name = payload.get("metric_name", "system.cpu.user")
        start = payload.get("start", 1717027200)  # Unix timestamp in seconds
        end = payload.get("end", 1717028800)
        resources = payload.get("resources", ["host:host1", "host:host2"])

        # Prepare query definitions for each resource
        queries = []
        for i, resource in enumerate(resources):
            query = MetricQueryForm(
                type=MetricQueryFormType.METRIC_QUERY_DEF,
                data=MetricQueryDefinition(
                    name=f"A{i+1}",
                    data_type=MetricQueryDataType.METRIC_QUERY_DATA_TYPE_METRIC,
                    query=f"{metric_name}{{ {resource} }}",
                    metadata=MetricQueryMetadata(
                        resource=MetricResourceQueryDefinition(name=resource)
                    )
                )
            )
            queries.append(query)

        # Create and execute the metric query
        query_form = MetricQueryForm(
            type=MetricQueryFormType.METRIC_QUERY_FORM_TYPE_QUERY_LIST,
            queries=queries,
            context="Compare metric series for two resources"
        )

        try:
            api_response: MetricQueryResponse = api_instance.query_metrics(
                query_form=query_form,
                from_ts=start,
                to_ts=end
            )

            # Process and return the result
            result = {
                "series": [
                    {
                        "resource": resource,
                        "points": [
                            (point.value, point.timestamp) for point in series.pointlist
                        ]
                    }
                    for resource, series in zip(resources, api_response.series)
                ],
                "status": "success"
            }
        except Exception as e:
            result = {
                "error": str(e),
                "status": "failed"
            }

    return result
